      "passage": "💬 **खालील संवाद काळजीपूर्वक वाचा व विचारलेल्या प्रश्नाचे योग्य उत्तर निवडा:**\n\n(गावातील चावडीवर शेती व परिसराच्या विकासाविषयी चर्चा सुरू आहे.)\n\nरोहन (उत्साहाने): \"गुरुजी, आपल्या गावात नवीन मोठा औद्योगिक कारखाना उभा राहिला पाहिजे. कारखान्यामुळे रोजगाराच्या संधी मिळतील आणि समृद्धी येईल!\"\nस्नेहा (गंभीरपणे): \"पण रोहन, केवळ कारखान्यांच्या मागे धावून कसे चालेल? रासायनिक धूर आणि सांडपाण्यामुळे शेतजमिनी नापीक होतील, हवा प्रदूषित होईल. आपल्याला पर्यावरणाचे संवर्धन सर्वप्रथम केलेच पाहिजे.\"\nरोहन: \"पर्यावरणाचा अतिरेकी विचार केल्यास औद्योगिकीकरण आणि भौतिक प्रगती कशी होणार?\"\nगुरुजी (हसतमुख चेहऱ्याने): \"दोघांचेही विचार महत्त्वाचे आहेत, मुलांनो! एका बाजूला आर्थिक विकासासाठी उद्योग हवेत, तर दुसऱ्या बाजूला जीवन जगण्यासाठी पर्यावरण रक्षण आवश्यक आहे. या दोघांत सुवर्णमध्य साधला पाहिजे. निसर्गाचा समतोल बिघडू न देता शाश्वत विकास साधणे हीच काळाची गरज आहे.\"\n(इतक्यात शेतकरी पुत्र रोहन पुढे येऊन म्हणाला): \"होय गुरुजी! मी शेतकरी पुत्र म्हणून पारंपारिक शेतीला जुनाट मानत नाही, तर आधुनिक सौरऊर्जा, ठिबक सिंचन व सेंद्रिय तंत्रज्ञानाची शेतीशी सांगड घालून कृषी उत्पादकता दुप्पट करण्याची जिद्द बाळगतो!\"",
