      "passage": "📖 **खालील वैचारिक गद्य उतारा काळजीपूर्वक वाचा व विचारलेल्या प्रश्नाचे योग्य उत्तर निवडा:**\n\n\"भारताचे माजी राष्ट्रपती भारतरत्न डॉ. ए. पी. जे. अब्दुल कलाम यांच्या मते, सुशिक्षित, संस्कारक्षम व कृतिशील युवाशक्ती हाच कोणत्याही राष्ट्राच्या विकासाचा सर्वात भक्कम कणा आहे. देशाची प्रगती केवळ भौतिक सुखसोयी किंवा पैशांच्या संचयनावर अवलंबून नसते, तर देशातील तरुणाईच्या मनात वैज्ञानिक दृष्टिकोन आणि स्वाभिमान किती जागृत आहे यावर ठरते. जेव्हा समाजात वैज्ञानिक दृष्टिकोनाचा अंगीकार केला जातो, तेव्हा शतकानुशतके चालत आलेल्या घातक अंधश्रद्धा आणि जुनाट रूढींचा लोप होऊन विवेकाची नवी पहाट उगवते. \n\nज्ञानाची खरी साधना केवळ घोकंपट्टी किंवा यांत्रिक पाठांतराने कधीच साध्य होत नाही; खरी ज्ञानप्राप्ती चिकित्सक विचार, निरीक्षण आणि स्वानुभवातूनच होते. या ज्ञानसाधनेत उत्तम पुस्तके माणसासाठी दीपस्तंभाचे काम करतात. पुस्तके ही केवळ करमणुकीचे साधन नसून ती माणसाची मूक मार्गदर्शक आणि आजीवन विश्वासू मित्र असतात. आयुष्याच्या वाटेवर संकटे ही अपरिहार्य असतात. परंतु ज्यांच्याजवळ दुर्दम्य इच्छाशक्ती, अविचल ध्येयनिष्ठा आणि अखंड आत्मविश्वास असतो, त्यांच्यापुढे संकटांचे महाकाय पर्वतही नतमस्तक होतात. म्हणूनच जीवनात नशिबाच्या भरवशावर हात बांधून बसण्यापेक्षा आत्मविश्वासाने, चिकाटीने आणि अढळ परिश्रमाने संकटांवर मात करून यशाचे उत्तुंग शिखर गाठणे, हाच प्रत्येक सुजाण नागरिकाचा जीवनमंत्र असला पाहिजे.\"",
      "question": "📖 **खालील वैचारिक गद्य उतारा काळजीपूर्वक वाचा व विचारलेल्या प्रश्नाचे योग्य उत्तर निवडा:**\n\n\"भारताचे माजी राष्ट्रपती भारतरत्न डॉ. ए. पी. जे. अब्दुल कलाम यांच्या मते, सुशिक्षित, संस्कारक्षम व कृतिशील युवाशक्ती हाच कोणत्याही राष्ट्राच्या विकासाचा सर्वात भक्कम कणा आहे. देशाची प्रगती केवळ भौतिक सुखसोयी किंवा पैशांच्या संचयनावर अवलंबून नसते, तर देशातील तरुणाईच्या मनात वैज्ञानिक दृष्टिकोन आणि स्वाभिमान किती जागृत आहे यावर ठरते. जेव्हा समाजात वैज्ञानिक दृष्टिकोनाचा अंगीकार केला जातो, तेव्हा शतकानुशतके चालत आलेल्या घातक अंधश्रद्धा आणि जुनाट रूढींचा लोप होऊन विवेकाची नवी पहाट उगवते. \n\nज्ञानाची खरी साधना केवळ घोकंपट्टी किंवा यांत्रिक पाठांतराने कधीच साध्य होत नाही; खरी ज्ञानप्राप्ती चिकित्सक विचार, निरीक्षण आणि स्वानुभवातूनच होते. या ज्ञानसाधनेत उत्तम पुस्तके माणसासाठी दीपस्तंभाचे काम करतात. पुस्तके ही केवळ करमणुकीचे साधन नसून ती माणसाची मूक मार्गदर्शक आणि आजीवन विश्वासू मित्र असतात. आयुष्याच्या वाटेवर संकटे ही अपरिहार्य असतात. परंतु ज्यांच्याजवळ दुर्दम्य इच्छाशक्ती, अविचल ध्येयनिष्ठा आणि अखंड आत्मविश्वास असतो, त्यांच्यापुढे संकटांचे महाकाय पर्वतही नतमस्तक होतात. म्हणूनच जीवनात नशिबाच्या भरवशावर हात बांधून बसण्यापेक्षा आत्मविश्वासाने, चिकाटीने आणि अढळ परिश्रमाने संकटांवर मात करून यशाचे उत्तुंग शिखर गाठणे, हाच प्रत्येक सुजाण नागरिकाचा जीवनमंत्र असला पाहिजे.\"\n\n**प्रश्न ९.** उताऱ्याच्या आधारे खालीलपैकी चुकीचे (असत्य) विधान कोणते?",
      "options": [
        "पुस्तके माणसाची मार्गदर्शक असतात.",
        "संकटांवर आत्मविश्वासाने मात करावी.",
        "युवाशक्ती देशाचा कणा आहे.",
        "केवळ पाठांतराने खरी ज्ञानप्राप्ती होते."
      ],
      "answer": 3,
      "explanation": "उताऱ्यानुसार पाठांतरापेक्षा आकलन आणि स्वानुभव महत्त्वाचा आहे, म्हणून हे विधान असत्य आहे.",
